import React from 'react';
import {createRoot} from 'react-dom/client';
import {Combobox as B} from '@base-ui/react/combobox';
import {Combobox,ComboboxInput,ComboboxContent,ComboboxList,ComboboxItem} from '../../registry/cadence/combobox';
import {Dialog,DialogTrigger,DialogContent,DialogTitle,DialogClose} from '../../registry/cadence/dialog';
import {CadenceProvider} from '../../registry/cadence/lib/provider';
const baseline=new URLSearchParams(location.search).has('base');
window.proof={changes:[],clicks:0};
function Combo(){return <div style={{margin:40,display:"inline-block",width:300,verticalAlign:"top"}}>{baseline?<B.Root items={['Alpha','Beta']} onOpenChange={v=>window.proof.changes.push(v)}><B.Input aria-label="Choice"/><B.Portal><B.Positioner><B.Popup style={{background:'white',padding:20,border:'1px solid'}}><B.List>{v=><B.Item key={v} value={v}>{v}</B.Item>}</B.List></B.Popup></B.Positioner></B.Portal></B.Root>:<Combobox items={['Alpha','Beta']} onOpenChange={v=>window.proof.changes.push(v)}><ComboboxInput aria-label="Choice"/><ComboboxContent style={{background:'white',padding:20,border:'1px solid'}}><ComboboxList>{v=><ComboboxItem key={v} value={v}>{v}</ComboboxItem>}</ComboboxList></ComboboxContent></Combobox>}</div>}
function App(){const [mounted,setMounted]=React.useState(true);window.setMounted=setMounted;return <CadenceProvider mode="none"><button id="before">Before</button><button id="prehidden" aria-hidden="true" tabIndex={3}>Hidden</button><button id="preinert" inert tabIndex={4}>Inert</button>{mounted&&(new URLSearchParams(location.search).has("dialog")?<Dialog><DialogTrigger>Open dialog</DialogTrigger><DialogContent style={{position:"fixed",left:80,top:80,zIndex:100,background:"white"}}><DialogTitle>Nested</DialogTitle><Combo/><button id="inside" onClick={()=>window.proof.clicks++}>Inside dialog</button><DialogClose>Close dialog</DialogClose></DialogContent></Dialog>:<><Combo/>{new URLSearchParams(location.search).has("siblings")&&<Combo/>}</>)}<button id="outside" style={{position:'fixed',left:500,top:300}} onClick={()=>window.proof.clicks++}>Outside</button></CadenceProvider>}
createRoot(document.getElementById('root')).render(<App/>);

