import {chromium,expect} from '@playwright/test';
import fs from 'node:fs';
const b=await chromium.launch({channel:'msedge',headless:true});const results=[];
for(const baseline of [true,false])for(const touch of [false,true]){
 const p=await b.newPage({hasTouch:touch});await p.goto('http://127.0.0.1:3156/'+(baseline?'?base':''));
 await p.getByRole('combobox').click();await p.getByRole('option').first().waitFor();
 const before=await p.evaluate(()=>({inert:document.querySelector('#outside').closest('[inert]')?.outerHTML.slice(0,160),hidden:document.querySelector('#outside').closest('[aria-hidden]')?.getAttribute('aria-hidden')}));
 if(touch)await p.touchscreen.tap(530,315);else await p.mouse.click(530,315);
 await p.waitForTimeout(100);results.push({baseline,touch,before,proof:await p.evaluate(()=>window.proof),open:await p.getByRole('option').count()});await p.close();
}
await b.close();fs.writeFileSync('.cache/compat-combobox-baseline.json',JSON.stringify(results,null,2));console.log(results);

