import {chromium,expect} from '@playwright/test';import fs from 'node:fs';
const b=await chromium.launch({channel:'msedge',headless:true});const reports=[];
for(const baseline of [true,false])for(const shift of [false,true]){
 const p=await b.newPage();await p.goto('http://127.0.0.1:3156/'+(baseline?'?base':''));await p.getByRole('combobox').click();await p.getByRole('option').first().waitFor();
 await p.keyboard.press(shift?'Shift+Tab':'Tab');await expect(p.getByRole('option')).toHaveCount(0);
 reports.push({case:'tab',baseline,shift,focus:await p.evaluate(()=>document.activeElement.id||document.activeElement.getAttribute('data-slot')||document.activeElement.tagName)});
 await expect(p.locator('#prehidden')).toHaveAttribute('aria-hidden','true');await expect(p.locator('#prehidden')).toHaveAttribute('tabindex','3');await expect(p.locator('#preinert')).toHaveAttribute('inert','');await p.close();
}
for(const nested of [false,true]){
 const p=await b.newPage();await p.goto('http://127.0.0.1:3156/'+(nested?'?dialog':''));if(nested)await p.getByText('Open dialog',{exact:true}).click();
 for(let i=0;i<2;i++) {await p.getByRole('combobox').click();await p.getByRole('option').first().waitFor();await p.keyboard.press('Escape');await expect(p.getByRole('option')).toHaveCount(0);}
 await p.getByRole('combobox').click();await p.getByRole('option').first().waitFor();
 if(!nested){await expect(p.locator('#outside')).toHaveAttribute('tabindex','-1');await p.locator('#outside').evaluate(e=>e.setAttribute('tabindex','2'));}
 await p.evaluate(()=>window.setMounted(false));await expect(p.getByRole('option')).toHaveCount(0);
 if(!nested)await expect(p.locator('#outside')).toHaveAttribute('tabindex','2');else {await expect(p.locator('#outside')).not.toHaveAttribute('tabindex');await expect(p.locator('#outside')).not.toHaveAttribute('aria-hidden');expect(await p.locator('#outside').evaluate(e=>e.inert)).toBe(false);}
 await expect(p.locator('#prehidden')).toHaveAttribute('aria-hidden','true');await expect(p.locator('#prehidden')).toHaveAttribute('tabindex','3');await expect(p.locator('#preinert')).toHaveAttribute('inert','');await expect(p.locator('#preinert')).toHaveAttribute('tabindex','4');
 reports.push({case:'reopen/unmount/caller-ownership',nested,outside:await p.locator('#outside').evaluate(e=>({inert:e.inert,hidden:e.getAttribute('aria-hidden'),tabindex:e.getAttribute('tabindex')}))});await p.close();
}
await b.close();fs.writeFileSync('.cache/compat-combobox-matrix.json',JSON.stringify(reports,null,2));console.log(reports);

