import {chromium,expect} from '@playwright/test';import fs from 'node:fs';const b=await chromium.launch({channel:'msedge',headless:true});const reports=[];
for(const touch of [false,true]){
 const p=await b.newPage({hasTouch:touch});await p.goto('http://127.0.0.1:3156/?dialog');await p.getByText('Open dialog',{exact:true}).click();await p.getByRole('combobox').click();await p.getByRole('option').first().waitFor();
 const pre=await p.locator('#outside').evaluate(e=>({inert:e.inert,hidden:e.getAttribute('aria-hidden'),tabindex:e.getAttribute('tabindex')}));
 const target=p.locator('#inside');if(touch)await target.tap();else await target.click();await expect(p.getByRole('option')).toHaveCount(0);await expect(p.getByRole('dialog')).toHaveCount(1);expect(await p.evaluate(()=>window.proof.clicks)).toBe(1);
 expect(await p.locator('#outside').evaluate(e=>({inert:e.inert,hidden:e.getAttribute('aria-hidden'),tabindex:e.getAttribute('tabindex')}))).toEqual(pre);
 await p.getByText('Close dialog',{exact:true}).click();await expect(p.getByRole('dialog')).toHaveCount(0);await expect(p.locator('#outside')).not.toHaveAttribute('aria-hidden');await expect(p.locator('#outside')).not.toHaveAttribute('tabindex');reports.push({case:'nested-parent-ownership',touch,pre});await p.close();
}
const p=await b.newPage();await p.goto('http://127.0.0.1:3156/?siblings');const inputs=p.locator('input[role=combobox]');await inputs.nth(0).click();await p.getByRole('option').first().waitFor();await inputs.nth(1).click();await expect(inputs.nth(0)).toHaveAttribute('aria-expanded','false');await expect(inputs.nth(1)).toHaveAttribute('aria-expanded','true');await expect(p.getByRole('option')).toHaveCount(2);await p.keyboard.press('Escape');await expect(p.getByRole('option')).toHaveCount(0);await expect(p.locator('#outside')).not.toHaveAttribute('tabindex');reports.push({case:'sibling-popup-close-order',passed:true});await b.close();fs.writeFileSync('.cache/compat-combobox-ownership.json',JSON.stringify(reports,null,2));console.log(reports);
